class LibrarySystem:
    def __init__(self):
        self.books = set()
        self.loans = {}  # 책 제목 -> 빌린 회원

    def add_book(self, title):
        self.books.add(title)

    def borrow(self, member, title):
        if title not in self.books:
            return "없는 책"
        if title in self.loans:
            return "대출 중"
        if len(self.borrowed_by(member)) >= 2:
            return "한도 초과"
        self.loans[title] = member
        return "대출 완료"

    def return_book(self, member, title):
        if self.loans.get(title) == member:
            del self.loans[title]
            return "반납 완료"
        return "빌린 책 아님"

    def borrowed_by(self, member):
        return sorted(t for t, m in self.loans.items() if m == member)

